// ——— CONFIGURATION ———————————————————————————————————————————
const CONFIG = {
  candidateName:    'Krish Rathi',
  candidateEmail:   'krishrathi877@gmail.com',
  candidatePhone:   '+91 93523 39808',
  linkedinUrl:      'linkedin.com/in/krish-rathi',
  githubUrl:        'github.com/krish',
  resumeDriveLink:  'https://drive.google.com/file/d/195RH99pePnHBWtZEs6SKL_kAtfX-JQFA/view?usp=sharing',
  googleSheetId:    '1t0az-y0QSBBDdt2F6P1jCWM40g8g96jLFyTmVYWv7jw',
  batchSize:        10,    // HRs to email per run (Changed to 10 as requested)
  dailyLimit:       50,    // hard daily cap
  delayBetweenMs:   8000,  // 8s between sends to avoid spam flags

  // Top skills for subject line personalisation
  topSkills: ['React', 'Next.js', 'AI/ML', 'LLM', 'Full Stack', 'Node.js', 'Firebase', 'AWS'],

  highlights: [
    'Chatbot Developer Intern @ RANNLAB – built RAG pipeline reducing support load 70%',
    'Facial recognition pipeline (AWS Rekognition) – 98.87% accuracy, 1000+ daily users',
    'StockVision – production AI stock platform with Gemini AI & real-time feeds',
    'KishanBhai – multilingual offline-first PWA for 100+ agricultural commodities',
    'IIT Ropar Hackathon Winner 2025, 3× national AI/ML wins',
    '280+ LeetCode/Codeforces problems – DP, Graphs, System Design'
  ]
};
// ————————————————————————————————————————————————————————————

const trigger = $input.first().json;
const isWebhook = trigger.headers !== undefined;

return [{ json: { config: CONFIG, isWebhook, timestamp: new Date().toISOString() } }];

const config = $('Config').first().json.config;
const hrList = $('Read HR List from Sheet').all().map(i => i.json);
const alreadySent = $('Read Already Sent Emails').all().map(i => i.json);

// Build set of already-emailed addresses
const sentEmails = new Set(alreadySent.map(r => (r.hr_email || '').toLowerCase().trim()));

// Filter out already-contacted, skip invalid rows
const pending = hrList.filter(hr => {
  const email = (hr.Email || '').toLowerCase().trim();
  return email &&
    email.includes('@') &&
    !sentEmails.has(email) &&
    hr.Name &&
    hr.Company;
});

// Take batch
const batch = pending.slice(0, config.batchSize);

console.log(`Pending: ${pending.length}, Sending batch of: ${batch.length}`);

if (batch.length === 0) {
  return [{ json: { _noBatch: true, message: 'No new HRs to contact in this run.', totalPending: 0 } }];
}

return batch.map((hr, idx) => ({
  json: {
    idx,
    hr_name:    hr.Name || '',
    hr_email:   hr.Email || '',
    hr_title:   hr.Title || 'HR',
    company:    (hr.Company || '').replace(/,$/, '').trim(),
    config,
    requestId:  `krish-${Date.now()}-${idx}`
  }
}));

const prev = $ ('Filter & Batch HRs').all();
const aiItems = $input.all();

// Match back to HR data using item index
const results = aiItems.map((item, idx) => {
  const rawText = item.json.text || '{}';
  let parsed = { subject: '', body: '' };

  try {
    let cleaned = rawText.trim();
    const start = cleaned.indexOf('{');
    const end = cleaned.lastIndexOf('}');
    if (start !== -1 && end !== -1) cleaned = cleaned.substring(start, end + 1);
    parsed = JSON.parse(cleaned);
  } catch (e) {
    // Fallback template if AI parse fails
    const hrData = prev[idx]?.json || {};
    parsed = {
      subject: `Internship / Full-Stack Role – Krish Rathi (AI/React/Next.js)`,
      body: `Hi ${hrData.hr_name || 'there'},\n\nI'm Krish Rathi, a CS student at BML Munjal with hands-on experience building AI-driven products. At RANNLAB I shipped a RAG chatbot that cut support load by 70%, and an AWS Rekognition pipeline at 98.87% accuracy.\n\nI'd love to explore opportunities at ${hrData.company || 'your company'}. Please find my resume attached – happy to chat for 10 minutes at your convenience.\n\nBest,\nKrish Rathi\n+91 93523 39808 | linkedin.com/in/krish-rathi`
    };
  }

  // Pull HR metadata from corresponding input batch item
  const hr = prev[idx]?.json || item.json;

  return {
    json: {
      hr_name:   hr.hr_name,
      hr_email:  hr.hr_email,
      hr_title:  hr.hr_title,
      company:   hr.company,
      subject:   parsed.subject,
      body:      parsed.body,
      requestId: hr.requestId,
      config:    hr.config
    }
  };
});

return results;

const input = $json;
const sent = $('Send Gmail with Resume').first()?.json;
const success = sent && !sent.error;

return [{
  json: {
    id:             input.requestId || `kr-${Date.now()}`,
    hr_name:        input.hr_name,
    hr_email:       input.hr_email,
    hr_title:       input.hr_title,
    company:        input.company,
    subject:        input.subject,
    status:         success ? 'sent' : 'failed',
    sent_at:        success ? new Date().toISOString() : '',
    opened_at:      '',
    replied_at:     '',
    follow_up_sent: 'no',
    error:          success ? '' : JSON.stringify(sent?.error || 'unknown'),
    notes:          ''
  }
}];

const allLogs = $input.all().map(i => i.json);
const sent    = allLogs.filter(r => r.status === 'sent').length;
const failed  = allLogs.filter(r => r.status === 'failed').length;

return [{
  json: {
    summary: `✅ Batch complete – Sent: ${sent}, Failed: ${failed}, Total: ${allLogs.length}`,
    sent, failed, total: allLogs.length,
    timestamp: new Date().toISOString()
  }
}];
